/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "(" + String(String(dma_audtWrtrptConn.get("audtPdStrtDd")).substring(0, 4)) + ")"; } },
        { childId: "__rb1", fn: function () { return "(" + String(String(dma_fsttrmAudtWrtrptConn.get("audtPdStrtDd")).substring(0, 4)) + ")"; } },
        { childId: "__rb26", fn: function () { return String(String((dma_pageContext.get("disclsPublDd") ?? ""))); } },
        { childId: "__rb27", fn: function () { return String(String((dma_pageContext.get("fsttrmDisclsPublDd") ?? ""))); } },
        { childId: "__rb50", fn: function () { return String(String((dma_pageContext.get("disclsPublDd") ?? ""))); } },
        { childId: "__rb51", fn: function () { return String(String((dma_pageContext.get("fsttrmDisclsPublDd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

